package com.gamehub.search;import com.gamehub.common.*;import com.gamehub.game.vo.GameCardVO;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/search") public class SearchController {private final SearchService service;public SearchController(SearchService service){this.service=service;}@GetMapping public ApiResponse<PageResult<GameCardVO>>search(@RequestParam String q,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String category,@RequestParam(required=false)String tag,@RequestParam(required=false)String platform,@RequestParam(required=false)String language,@RequestParam(required=false,defaultValue="relevance")String sort){return ApiResponse.ok(service.search(q,page,Math.min(size,60),category,tag,platform,language,sort));}}
